import{bV as a,aL as r,u as o,G as t}from"./chunks/framework.BfzMay2U.js";const g=JSON.parse('{"title":"制造业 PHP 面试题：Laravel 与后端开发（01—25）","description":"","frontmatter":{"title":"制造业 PHP 面试题：Laravel 与后端开发（01—25）","date":"2026-11-15T10:00:00.000Z","categories":["面试","PHP"],"tags":["PHP","Laravel","MES","权限控制","队列"],"sidebarSort":1},"headers":[],"relativePath":"php/jd/laravel-php-interview.md","filePath":"php/jd/laravel-php-interview.md"}'),n={name:"php/jd/laravel-php-interview.md"};function l(s,e,i,d,c,h){return r(),o("div",null,[...e[0]||(e[0]=[t('<h1 id="制造业-php-面试题-laravel-与后端开发-01—25" tabindex="-1">制造业 PHP 面试题：Laravel 与后端开发（01—25） <a class="header-anchor" href="#制造业-php-面试题-laravel-与后端开发-01—25" aria-label="Permalink to &quot;制造业 PHP 面试题：Laravel 与后端开发（01—25）&quot;">​</a></h1><p>本系列按 MES、E-DHR、ERP 对接、OA 流程及 UniApp 岗位 JD 整理，共 150 道题。本篇覆盖后端开发基本功，每题的参考回答都可以先概括，再结合自己的真实项目展开。</p><div class="tip custom-block"><p class="custom-block-title">阅读说明</p><p>示例以 PHP 8.x、Laravel 常见能力为背景，具体 API 和默认配置应核对项目版本。所有场景均为面试设计案例，不代表本人已交付的项目经历。</p></div><h2 id="一、语言基础与请求处理" tabindex="-1">一、语言基础与请求处理 <a class="header-anchor" href="#一、语言基础与请求处理" aria-label="Permalink to &quot;一、语言基础与请求处理&quot;">​</a></h2><h3 id="_01-php-中-和-有什么区别-生产系统为什么要关注" tabindex="-1">01. PHP 中 <code>==</code> 和 <code>===</code> 有什么区别？生产系统为什么要关注？ <a class="header-anchor" href="#_01-php-中-和-有什么区别-生产系统为什么要关注" aria-label="Permalink to &quot;01. PHP 中 `==` 和 `===` 有什么区别？生产系统为什么要关注？&quot;">​</a></h3><p><strong>参考回答：</strong> <code>==</code> 会进行类型转换，<code>===</code> 同时比较类型和值。接口中的工单状态、布尔值和数量应先校验并规范类型，再做严格比较，避免字符串、数字和空值被当成同一种含义。不同 PHP 版本的宽松比较细节有差异，不应依赖隐式转换完成业务判断。</p><p><strong>追问要点：</strong> <code>empty(&#39;0&#39;)</code> 为真，<code>isset()</code> 无法区分字段不存在和字段值为 <code>null</code>。判断是否传入字段可用 <code>array_key_exists()</code>，判断必填和数值范围则使用明确的校验规则。</p><h3 id="_02-null、空字符串、零和未传字段应该如何区分" tabindex="-1">02. <code>null</code>、空字符串、零和未传字段应该如何区分？ <a class="header-anchor" href="#_02-null、空字符串、零和未传字段应该如何区分" aria-label="Permalink to &quot;02. `null`、空字符串、零和未传字段应该如何区分？&quot;">​</a></h3><p><strong>参考回答：</strong> 它们可能对应“未知”“主动清空”“实际值为零”“本次不修改”四种不同语义。例如更新工艺参数时，未传字段应保持原值，零可能是有效测量值，不能统一过滤为无数据。应在接口契约中写清可空、必填和局部更新规则。</p><p><strong>场景追问：</strong> Laravel 的字符串修剪、空字符串转 <code>null</code> 中间件会影响输入，应检查项目配置；<code>sometimes</code>、<code>nullable</code>、<code>present</code> 的使用由业务语义决定，不能互相替代。</p><h3 id="_03-php-的值传递、引用和写时复制怎么理解" tabindex="-1">03. PHP 的值传递、引用和写时复制怎么理解？ <a class="header-anchor" href="#_03-php-的值传递、引用和写时复制怎么理解" aria-label="Permalink to &quot;03. PHP 的值传递、引用和写时复制怎么理解？&quot;">​</a></h3><p><strong>参考回答：</strong> PHP 数组赋值通常使用写时复制，未修改时不必立即复制全部内容；写入后可能产生额外内存开销。引用会让变量共享同一变量容器，不能用来保证并发安全。对象变量持有对象标识，传给方法后修改对象属性会影响同一个对象，但重新给形参赋对象不会自动替换调用方变量。</p><p><strong>追问要点：</strong> <code>foreach ($rows as &amp;$row)</code> 结束后要解除残留引用，例如 <code>unset($row)</code>。批量导出时应优先减少加载量，而不是滥用引用“优化内存”。</p><h3 id="_04-接口、抽象类、trait-分别适合什么场景" tabindex="-1">04. 接口、抽象类、Trait 分别适合什么场景？ <a class="header-anchor" href="#_04-接口、抽象类、trait-分别适合什么场景" aria-label="Permalink to &quot;04. 接口、抽象类、Trait 分别适合什么场景？&quot;">​</a></h3><p><strong>参考回答：</strong> 接口定义协作契约，例如 ERP 客户端提供发送和查询能力；抽象类适合确有公共流程和可替换步骤的实现；Trait 复用少量横向行为，但容易隐藏依赖和产生方法冲突。对接一家 ERP 时可以先用普通服务类，多实现确实出现时再引入接口。</p><p><strong>追问要点：</strong> 不要为了“可扩展”建立大量空接口和基类。复用必须保留每个供应商不同的鉴权、错误码和重试语义。</p><h3 id="_05-composer-和-psr-4-自动加载解决什么问题" tabindex="-1">05. Composer 和 PSR-4 自动加载解决什么问题？ <a class="header-anchor" href="#_05-composer-和-psr-4-自动加载解决什么问题" aria-label="Permalink to &quot;05. Composer 和 PSR-4 自动加载解决什么问题？&quot;">​</a></h3><p><strong>参考回答：</strong> Composer 管理依赖与版本，PSR-4 约定命名空间到目录的映射，减少手写 <code>require</code>。应用项目应提交 <code>composer.lock</code>，部署执行 <code>composer install</code> 复现依赖，升级依赖才执行 <code>composer update</code>。生产环境可按项目要求关闭开发依赖并优化自动加载。</p><p><strong>场景追问：</strong> 本地正常、Linux 找不到类，先查文件名大小写、命名空间、目录映射和部署产物，再重建自动加载；不要直接在生产环境升级所有依赖。</p><h3 id="_06-php-fpm、nginx、laravel-之间是什么关系" tabindex="-1">06. PHP-FPM、Nginx、Laravel 之间是什么关系？ <a class="header-anchor" href="#_06-php-fpm、nginx、laravel-之间是什么关系" aria-label="Permalink to &quot;06. PHP-FPM、Nginx、Laravel 之间是什么关系？&quot;">​</a></h3><p><strong>参考回答：</strong> Nginx 处理连接和静态资源，并通过 FastCGI 将 PHP 请求交给 PHP-FPM；FPM 的工作进程执行 Laravel 入口文件和请求流程。响应慢要区分连接等待、FPM 队列、应用执行、SQL 和外部调用，不能仅凭“CPU 不高”判断没有容量问题。</p><p><strong>追问要点：</strong> FPM 进程数受单进程内存和总内存约束；增加进程还可能压垮 MySQL。排查结合慢日志、活跃进程、等待队列和下游连接数。</p><h2 id="二、laravel-工程实现" tabindex="-1">二、Laravel 工程实现 <a class="header-anchor" href="#二、laravel-工程实现" aria-label="Permalink to &quot;二、Laravel 工程实现&quot;">​</a></h2><h3 id="_07-laravel-的一次请求通常经过哪些环节" tabindex="-1">07. Laravel 的一次请求通常经过哪些环节？ <a class="header-anchor" href="#_07-laravel-的一次请求通常经过哪些环节" aria-label="Permalink to &quot;07. Laravel 的一次请求通常经过哪些环节？&quot;">​</a></h3><p><strong>参考回答：</strong> 从 Web 入口启动应用和服务容器，经中间件、路由匹配、参数与权限校验、控制器、业务服务和数据库，最后生成响应并经过响应中间件。实际启动文件和异常配置位置随版本不同，但认证、授权、规则、事务、输出的职责划分不变。</p><p><strong>场景追问：</strong> 报工接口的参数格式可在 Form Request 校验；工单是否允许报工、是否超量等动态规则应在业务服务中基于当前数据库状态判断。</p><h3 id="_08-服务容器和服务提供者有什么区别" tabindex="-1">08. 服务容器和服务提供者有什么区别？ <a class="header-anchor" href="#_08-服务容器和服务提供者有什么区别" aria-label="Permalink to &quot;08. 服务容器和服务提供者有什么区别？&quot;">​</a></h3><p><strong>参考回答：</strong> 容器负责依赖解析和对象构建，服务提供者负责向应用注册、启动相关能力。例如把 <code>ErpClient</code> 契约绑定到具体实现，再通过构造函数注入同步服务。<code>register()</code> 通常注册绑定，<code>boot()</code> 用于依赖注册完成后的启动配置。</p><p><strong>追问要点：</strong> <code>singleton</code> 的生命周期要结合运行方式判断。常驻进程中不能把当前用户、租户、请求对象存到跨请求复用的单例中，否则可能发生数据串用。</p><h3 id="_09-控制器、service、model-应怎样分工" tabindex="-1">09. 控制器、Service、Model 应怎样分工？ <a class="header-anchor" href="#_09-控制器、service、model-应怎样分工" aria-label="Permalink to &quot;09. 控制器、Service、Model 应怎样分工？&quot;">​</a></h3><p><strong>参考回答：</strong> 控制器协调输入输出，Service 表达业务动作与事务边界，Model 表达持久化和关联。报工服务负责检查状态、扣料、更新进度及写审计；控制器不承担这些规则。已有简单 CRUD 不必强制增加 Repository 等多层转发。</p><p><strong>追问要点：</strong> 同一动作可能由 HTTP、队列或定时任务触发，核心规则应复用同一业务入口，避免每条路径复制一套状态判断。</p><h3 id="_10-form-request-校验通过后-为什么还要校验业务规则" tabindex="-1">10. Form Request 校验通过后，为什么还要校验业务规则？ <a class="header-anchor" href="#_10-form-request-校验通过后-为什么还要校验业务规则" aria-label="Permalink to &quot;10. Form Request 校验通过后，为什么还要校验业务规则？&quot;">​</a></h3><p><strong>参考回答：</strong> Form Request 能验证必填、格式和部分存在性，但校验之后工单或库存仍可能被其他请求修改。关键动态条件必须在事务内通过锁或条件更新再次验证。例如“物料批次存在”并不等于“当前用户可用、未过期、已放行且库存足够”。</p><p><strong>追问要点：</strong> 不能把 <code>exists</code> 规则当成数据权限，也不能用请求前的 <code>unique</code> 校验替代数据库唯一约束。</p><h3 id="_11-如何防止批量赋值导致越权" tabindex="-1">11. 如何防止批量赋值导致越权？ <a class="header-anchor" href="#_11-如何防止批量赋值导致越权" aria-label="Permalink to &quot;11. 如何防止批量赋值导致越权？&quot;">​</a></h3><p><strong>参考回答：</strong> 只从已校验数据中提取允许写入的业务字段，并用 <code>$fillable</code> 等配置限制批量赋值。工厂 ID、创建人、审核人和放行状态应由服务端身份与业务动作决定，不能接收客户端任意指定。批量赋值保护也不能替代资源授权和字段权限。</p><p><strong>场景追问：</strong> 用户往报工 JSON 加入 <code>approved_by</code> 或 <code>factory_id</code>，接口应该拒绝或忽略非契约字段，并验证最终记录的归属正确。</p><h3 id="_12-eloquent-的-n-1-问题如何发现和解决" tabindex="-1">12. Eloquent 的 N+1 问题如何发现和解决？ <a class="header-anchor" href="#_12-eloquent-的-n-1-问题如何发现和解决" aria-label="Permalink to &quot;12. Eloquent 的 N+1 问题如何发现和解决？&quot;">​</a></h3><p><strong>参考回答：</strong> 列表先查询 N 条工单，再逐条访问产品或车间关联，就可能额外执行 N 次查询。可通过查询日志、性能追踪和测试查询数发现，用 <code>with()</code> 预加载，计数场景用 <code>withCount()</code>，同时限制字段和关联范围。</p><p><strong>追问要点：</strong> 预加载不是越多越好，加载完整物料明细可能耗尽内存。报表可使用聚合查询，并检查关联条件的数据权限。</p><h3 id="_13-middleware、gate-和-policy-应如何选择" tabindex="-1">13. Middleware、Gate 和 Policy 应如何选择？ <a class="header-anchor" href="#_13-middleware、gate-和-policy-应如何选择" aria-label="Permalink to &quot;13. Middleware、Gate 和 Policy 应如何选择？&quot;">​</a></h3><p><strong>参考回答：</strong> Middleware 适合认证、限流和请求级约束；Gate 适合相对简单的动作授权；Policy 适合围绕工单、批记录等资源集中管理授权。组织范围和字段权限仍需落到查询及写入逻辑，前端隐藏按钮只改善操作体验。</p><p><strong>场景追问：</strong> 用户能查看 A 工厂，不代表能通过导出接口下载 B 工厂批次；列表、详情、导出、附件和异步任务都要遵守同样的数据范围。</p><h3 id="_14-event、listener-和-job-如何区分" tabindex="-1">14. Event、Listener 和 Job 如何区分？ <a class="header-anchor" href="#_14-event、listener-和-job-如何区分" aria-label="Permalink to &quot;14. Event、Listener 和 Job 如何区分？&quot;">​</a></h3><p><strong>参考回答：</strong> Event 表达业务事实，例如报工已确认；Listener 响应该事实；Job 表达可调度执行的工作，例如同步 ERP。监听器既可以同步也可以排队，异步 Job 需要独立考虑重复投递、超时、重试和失败管理。</p><p><strong>追问要点：</strong> 扣料、报工和关键审计若必须一起成功，应在同一本地事务完成，不能依赖异步监听器“最终补齐”本应原子的核心记录。</p><h3 id="_15-为什么队列任务通常要在数据库事务提交后派发" tabindex="-1">15. 为什么队列任务通常要在数据库事务提交后派发？ <a class="header-anchor" href="#_15-为什么队列任务通常要在数据库事务提交后派发" aria-label="Permalink to &quot;15. 为什么队列任务通常要在数据库事务提交后派发？&quot;">​</a></h3><p><strong>参考回答：</strong> 提交前派发，消费者可能读不到新记录，或处理随后被回滚的数据。Laravel 可通过连接的 <code>after_commit</code> 配置或任务的 <code>afterCommit()</code> 延后派发，但仍需核对实际队列驱动和版本配置。</p><p><strong>关键边界：</strong> 提交后派发仍存在“数据库已提交、进程在入队前崩溃”的窗口。必须可靠送达的集成事件，可将 outbox 事件与业务数据同事务保存，再由后台扫描发送。</p><h3 id="_16-队列的-timeout、retry-after-和重试次数怎么设置" tabindex="-1">16. 队列的 <code>timeout</code>、<code>retry_after</code> 和重试次数怎么设置？ <a class="header-anchor" href="#_16-队列的-timeout、retry-after-和重试次数怎么设置" aria-label="Permalink to &quot;16. 队列的 `timeout`、`retry_after` 和重试次数怎么设置？&quot;">​</a></h3><p><strong>参考回答：</strong> 外部 HTTP 超时应小于任务可用执行时间；worker 的有效超时应小于任务重新可见或被重投的时间，并留清理余量。否则第一次任务尚未停止，第二个 worker 就可能再次执行。SQS 等驱动使用对应的可见性超时，应按驱动核对。</p><p><strong>追问要点：</strong> 重试配置区分网络故障与业务拒绝，使用有限次数和退避。即使配置正确，进程崩溃也会带来重复执行，因此业务幂等必不可少。</p><h3 id="_17-shouldbeunique-能保证业务绝不重复吗" tabindex="-1">17. <code>ShouldBeUnique</code> 能保证业务绝不重复吗？ <a class="header-anchor" href="#_17-shouldbeunique-能保证业务绝不重复吗" aria-label="Permalink to &quot;17. `ShouldBeUnique` 能保证业务绝不重复吗？&quot;">​</a></h3><p><strong>参考回答：</strong> 不能。它利用缓存锁抑制一定范围内的重复任务派发，实际行为受锁期限、缓存共享和任务生命周期影响。业务记录必须使用稳定业务键、数据库唯一约束和事务控制，消费者遇到重复请求返回原结果。</p><p><strong>场景追问：</strong> ERP 已入库但任务响应丢失，唯一任务锁无法证明远端结果；应按原业务键查询远端或安全重发，不生成新入库单号。</p><h3 id="_18-laravel-中怎样选择事务边界" tabindex="-1">18. Laravel 中怎样选择事务边界？ <a class="header-anchor" href="#_18-laravel-中怎样选择事务边界" aria-label="Permalink to &quot;18. Laravel 中怎样选择事务边界？&quot;">​</a></h3><p><strong>参考回答：</strong> 将必须同时生效的本地写入放在一个事务中，例如报工、扣料、库存流水、审计和 outbox。事务外执行慢速外部调用，避免持锁等待。跨数据库或跨系统的一致性要另做可靠消息、补偿和对账，不能靠一个 <code>DB::transaction()</code> 覆盖。</p><p><strong>追问要点：</strong> 死锁重试可能重新执行事务闭包，闭包内不应发送不可撤销的外部请求或重复发通知。失败要保留可定位的异常和业务上下文。</p><h3 id="_19-多实例部署的定时任务怎样避免重复执行" tabindex="-1">19. 多实例部署的定时任务怎样避免重复执行？ <a class="header-anchor" href="#_19-多实例部署的定时任务怎样避免重复执行" aria-label="Permalink to &quot;19. 多实例部署的定时任务怎样避免重复执行？&quot;">​</a></h3><p><strong>参考回答：</strong> 先明确哪个节点负责调度，再根据部署方式使用 Laravel 的单服务器调度、重叠执行锁或平台调度能力；涉及锁时需使用所有实例共享且支持相应能力的缓存。调度层防重减少重复启动，任务内部仍要按业务键幂等。</p><p><strong>追问要点：</strong> 进程崩溃可能留下未过期锁，应设置合理锁期限并提供受控恢复方式。对账任务要分批、可续跑，避免一次执行阻塞下一周期。</p><h2 id="三、安全、性能与可维护性" tabindex="-1">三、安全、性能与可维护性 <a class="header-anchor" href="#三、安全、性能与可维护性" aria-label="Permalink to &quot;三、安全、性能与可维护性&quot;">​</a></h2><h3 id="_20-数据库更新成功后-缓存怎样保持一致" tabindex="-1">20. 数据库更新成功后，缓存怎样保持一致？ <a class="header-anchor" href="#_20-数据库更新成功后-缓存怎样保持一致" aria-label="Permalink to &quot;20. 数据库更新成功后，缓存怎样保持一致？&quot;">​</a></h3><p><strong>参考回答：</strong> 常见方式是数据库提交后删除相关缓存，读取未命中再回源。删除失败应能重试，缓存要有合理过期时间；并发读写仍可能出现旧值回填窗口，强一致的扣料、放行和权限判断应读取权威数据，必要时使用版本化缓存策略。</p><p><strong>追问要点：</strong> 缓存键应包含工厂、权限范围和规则版本等必要维度，不能让不同组织共享同一份敏感报表结果。</p><h3 id="_21-异常、日志和接口响应应该怎样统一" tabindex="-1">21. 异常、日志和接口响应应该怎样统一？ <a class="header-anchor" href="#_21-异常、日志和接口响应应该怎样统一" aria-label="Permalink to &quot;21. 异常、日志和接口响应应该怎样统一？&quot;">​</a></h3><p><strong>参考回答：</strong> 区分输入错误、无权限、状态冲突、依赖故障和程序异常，对外返回稳定错误码与可读信息，对内记录关联 ID、业务键、耗时和异常堆栈。未知异常不应被吞掉并转换为“操作成功”，也不能向客户端暴露 SQL、密码或内部路径。</p><p><strong>追问要点：</strong> 已提交但外部同步失败，应返回明确的同步状态，而不是把已发生的本地动作描述成完全失败，引导用户不断重提。</p><h3 id="_22-sql-注入、xss、csrf-应分别怎样防" tabindex="-1">22. SQL 注入、XSS、CSRF 应分别怎样防？ <a class="header-anchor" href="#_22-sql-注入、xss、csrf-应分别怎样防" aria-label="Permalink to &quot;22. SQL 注入、XSS、CSRF 应分别怎样防？&quot;">​</a></h3><p><strong>参考回答：</strong> SQL 使用参数绑定，动态排序字段走白名单；XSS 按输出上下文转义，富文本按规则净化；CSRF 针对浏览器自动携带的 Cookie 凭证采用令牌和来源等控制。使用 Bearer Token 的 API 也要防 XSS 窃取令牌和跨域配置错误。</p><p><strong>追问要点：</strong> CORS 不能代替授权；模板转义不能保护任意 JavaScript、URL 上下文；<code>orderByRaw()</code> 不能直接拼用户输入。</p><h3 id="_23-文件上传和下载有哪些关键安全要求" tabindex="-1">23. 文件上传和下载有哪些关键安全要求？ <a class="header-anchor" href="#_23-文件上传和下载有哪些关键安全要求" aria-label="Permalink to &quot;23. 文件上传和下载有哪些关键安全要求？&quot;">​</a></h3><p><strong>参考回答：</strong> 校验大小、类型和内容，使用服务端生成的存储名，将附件放在不可直接执行的存储区。下载时按工厂、批次及角色授权，短期签名链接应控制有效期，敏感附件按要求记录访问。文件路径不能由用户直接拼接。</p><p><strong>场景追问：</strong> 检验报告上传后还应记录摘要、版本和关联业务；压缩包需限制解压规模与路径，避免路径穿越和资源耗尽。</p><h3 id="_24-大报表导出和长驻队列为什么容易内存增长" tabindex="-1">24. 大报表导出和长驻队列为什么容易内存增长？ <a class="header-anchor" href="#_24-大报表导出和长驻队列为什么容易内存增长" aria-label="Permalink to &quot;24. 大报表导出和长驻队列为什么容易内存增长？&quot;">​</a></h3><p><strong>参考回答：</strong> 一次加载全部数据、保留集合引用、缓存巨大对象以及循环生成文件都可能增加内存。导出按稳定主键分批读取，采用支持流式写出的格式或现有导出库，限制关联加载；长驻 worker 通过生命周期配置回收，并排查持续增长的根因。</p><p><strong>追问要点：</strong> <code>cursor()</code> 不代表所有数据库驱动都零缓冲；应实测驱动、ORM 和导出库的内存表现。OPcache 缓存字节码，不能替代数据查询优化。</p><h3 id="_25-如何证明一个-laravel-报工接口可以上线" tabindex="-1">25. 如何证明一个 Laravel 报工接口可以上线？ <a class="header-anchor" href="#_25-如何证明一个-laravel-报工接口可以上线" aria-label="Permalink to &quot;25. 如何证明一个 Laravel 报工接口可以上线？&quot;">​</a></h3><p><strong>参考回答：</strong> 除正常提交外，验证无权限、跨工厂、重复请求、同键不同内容、超量报工、库存竞争、事务回滚、队列重复执行和外部超时。检查报工、库存流水、审计、outbox 的一致性，并在接近真实数据规模的环境观察耗时、锁等待和错误率。</p><p><strong>追问要点：</strong> 使用框架 HTTP Fake 测外部故障，但行锁和死锁应使用与生产相近的 MySQL 环境验证；不能用 SQLite 通过的测试推断 MySQL 并发行为。</p><h2 id="延伸阅读" tabindex="-1">延伸阅读 <a class="header-anchor" href="#延伸阅读" aria-label="Permalink to &quot;延伸阅读&quot;">​</a></h2><ul><li><a href="./mysql-concurrency-interview.html">下一篇：MySQL、并发与报表（26—50）</a></li><li><a href="./../">返回 PHP 面试指南</a></li><li><a href="https://laravel.com/docs/12.x/container" target="_blank" rel="noreferrer">Laravel 服务容器</a></li><li><a href="https://laravel.com/docs/12.x/queues" target="_blank" rel="noreferrer">Laravel 队列</a></li><li><a href="https://laravel.com/docs/12.x/database" target="_blank" rel="noreferrer">Laravel 数据库与事务</a></li></ul>',83)])])}const u=a(n,[["render",l]]);export{g as __pageData,u as default};
